css:
/* From Uiverse.io by Thomasfadi  - Tags: action, card, creative */
.__UIV_SCOPE__ .logo svg {
  height: 48px;
  width: 54px;
}

.__UIV_SCOPE__ ::selection {
  background-color: rgba(0, 0, 0, 0);
}

.__UIV_SCOPE__ .container {
  position: absolute;
  left: 50%;
  top: 50%;
  transform: translate(-50%, -50%);
}

.__UIV_SCOPE__ .card {
  background: radial-gradient(circle, white 0%, #d5d5d5 100%);
  width: 300px;
  height: 200px;
  border-radius: 20px;
  position: relative;
  box-shadow: 3px 3px 17px 0px rgba(0, 0, 0, 0.55);
}

.__UIV_SCOPE__ .card .remove,
.__UIV_SCOPE__ .card .logo {
  position: absolute;
  display: inline-block;
  cursor: pointer;
}

.__UIV_SCOPE__ .card .remove {
  top: 30px;
  right: 30px;
  opacity: 0.9;
  color: black;
}

.__UIV_SCOPE__ .card .remove:hover {
  color: #f06b5d;
}

.__UIV_SCOPE__ .card .logo {
  top: 20px;
  left: 30px;
  font-size: 3em;
  opacity: 1;
}

.__UIV_SCOPE__ .card .number,
.__UIV_SCOPE__ .card .owner {
  display: block;
  position: absolute;
  left: 30px;
  cursor: default;
  color: black;
  opacity: 0.9;
  transition: color 0.7s ease-out;
}

.__UIV_SCOPE__ .card .number {
  bottom: 60px;
  letter-spacing: 4px;
}

.__UIV_SCOPE__ .card .owner {
  bottom: 30px;
  letter-spacing: 1px;
}
.__UIV_SCOPE__ .wave-group {
  position: relative;
}

.__UIV_SCOPE__ .wave-group .input {
  font-size: 16px;
  padding: 10px 10px 10px 5px;
  display: block;
  width: 200px;
  border: none;
  border-bottom: 1px solid #515151;
  background: transparent;
}

.__UIV_SCOPE__ .wave-group .input:focus {
  outline: none;
}

.__UIV_SCOPE__ .wave-group .label {
  color: #999;
  font-size: 18px;
  font-weight: normal;
  position: absolute;
  pointer-events: none;
  left: 5px;
  top: 10px;
  display: flex;
}

.__UIV_SCOPE__ .wave-group .label-char {
  transition: 0.2s ease all;
  transition-delay: calc(var(--index) * 0.05s);
}

.__UIV_SCOPE__ .wave-group .input:focus ~ label .label-char,
.__UIV_SCOPE__ .wave-group .input:valid ~ label .label-char {
  transform: translateY(-20px);
  font-size: 14px;
  color: #6e7fc1;
}

.__UIV_SCOPE__ .wave-group .bar {
  position: relative;
  display: block;
  width: 200px;
}

.__UIV_SCOPE__ .wave-group .bar:before,
.__UIV_SCOPE__ .wave-group .bar:after {
  content: "";
  height: 2px;
  width: 0;
  bottom: 1px;
  position: absolute;
  background: #0727a6;
  transition: 0.2s ease all;
  -moz-transition: 0.2s ease all;
  -webkit-transition: 0.2s ease all;
}

.__UIV_SCOPE__ .wave-group .bar:before {
  left: 50%;
}

.__UIV_SCOPE__ .wave-group .bar:after {
  right: 50%;
}

.__UIV_SCOPE__ .wave-group .input:focus ~ .bar:before,
.__UIV_SCOPE__ .wave-group .input:focus ~ .bar:after {
  width: 50%;
}
